) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP VIEW IF EXISTS `user_activity_summary`;
CREATE TABLE `user_activity_summary` (`user_id` bigint(20) unsigned, `user_name` varchar(255), `user_email` varchar(255), `total_invoices` bigint(21), `total_clients` bigint(21), `total_suppliers` bigint(21), `total_products` bigint(21), `last_invoice_date` timestamp, `invoices_last_30_days` decimal(22,0), `invoices_last_7_days` decimal(22,0));


DROP TABLE IF EXISTS `database_size_monitor`;
CREATE ALGORITHM=UNDEFINED DEFINER=`invoice`@`%` SQL SECURITY DEFINER VIEW `database_size_monitor` AS select `information_schema`.`TABLES`.`TABLE_NAME` AS `table_name`,`information_schema`.`TABLES`.`TABLE_ROWS` AS `row_count`,round((`information_schema`.`TABLES`.`DATA_LENGTH` + `information_schema`.`TABLES`.`INDEX_LENGTH`) / 1024 / 1024,2) AS `size_mb`,round(`information_schema`.`TABLES`.`DATA_LENGTH` / 1024 / 1024,2) AS `data_size_mb`,round(`information_schema`.`TABLES`.`INDEX_LENGTH` / 1024 / 1024,2) AS `index_size_mb`,`information_schema`.`TABLES`.`ENGINE` AS `storage_engine` from `information_schema`.`TABLES` where `information_schema`.`TABLES`.`TABLE_SCHEMA` = database() order by `information_schema`.`TABLES`.`DATA_LENGTH` + `information_schema`.`TABLES`.`INDEX_LENGTH` desc;

DROP TABLE IF EXISTS `invoice_statistics`;
CREATE ALGORITHM=UNDEFINED DEFINER=`invoice`@`%` SQL SECURITY DEFINER VIEW `invoice_statistics` AS select date_format(`invoices`.`issue_date`,'%Y-%m') AS `month_year`,`invoices`.`user_id` AS `user_id`,count(0) AS `invoice_count`,sum(`invoices`.`payment_amount`) AS `total_revenue`,avg(`invoices`.`payment_amount`) AS `avg_invoice_amount`,min(`invoices`.`payment_amount`) AS `min_invoice_amount`,max(`invoices`.`payment_amount`) AS `max_invoice_amount`,count(case when `invoices`.`payment_status_id` = 1 then 1 end) AS `paid_invoices`,count(case when `invoices`.`payment_status_id` = 2 then 1 end) AS `unpaid_invoices`,count(case when `invoices`.`payment_status_id` = 3 then 1 end) AS `overdue_invoices` from `invoices` where `invoices`.`issue_date` >= current_timestamp() - interval 24 month group by date_format(`invoices`.`issue_date`,'%Y-%m'),`invoices`.`user_id` order by date_format(`invoices`.`issue_date`,'%Y-%m') desc,`invoices`.`user_id`;

DROP TABLE IF EXISTS `user_activity_summary`;
CREATE ALGORITHM=UNDEFINED DEFINER=`invoice`@`%` SQL SECURITY DEFINER VIEW `user_activity_summary` AS select `u`.`id` AS `user_id`,`u`.`name` AS `user_name`,`u`.`email` AS `user_email`,count(distinct `i`.`id`) AS `total_invoices`,count(distinct `c`.`id`) AS `total_clients`,count(distinct `s`.`id`) AS `total_suppliers`,count(distinct `p`.`id`) AS `total_products`,max(`i`.`created_at`) AS `last_invoice_date`,sum(case when `i`.`created_at` >= current_timestamp() - interval 30 day then 1 else 0 end) AS `invoices_last_30_days`,sum(case when `i`.`created_at` >= current_timestamp() - interval 7 day then 1 else 0 end) AS `invoices_last_7_days` from ((((`users` `u` left join `invoices` `i` on(`u`.`id` = `i`.`user_id`)) left join `clients` `c` on(`u`.`id` = `c`.`user_id`)) left join `suppliers` `s` on(`u`.`id` = `s`.`user_id`)) left join `products` `p` on(`u`.`id` = `p`.`user_id`)) group by `u`.`id`,`u`.`name`,`u`.`email`;

