INSERT INTO `mysql_optimization_logs` (`id`, `setting_name`, `current_value`, `recommended_value`, `description`, `priority`, `applied`, `created_at`, `updated_at`) VALUES
(1,	'innodb_buffer_pool_size',	'128M',	'512M',	'InnoDB buffer pool should be 70-80% of available RAM for dedicated MySQL server. For shared server, 25-50% is recommended. Increases cache hit ratio for frequently accessed data.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(2,	'query_cache_size',	'0',	'64M',	'Query cache stores result of SELECT statements for faster repeated queries. Recommended size is 64-128MB for applications with many repeated SELECT queries.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(3,	'query_cache_type',	'OFF',	'ON',	'Enables query cache to store and reuse results of SELECT statements. Significantly improves performance for read-heavy applications like invoice management systems.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(4,	'max_connections',	'151',	'200',	'Maximum number of concurrent connections. Should be set based on expected concurrent users. Too low causes connection errors, too high wastes memory.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(5,	'innodb_log_file_size',	'48M',	'128M',	'Size of InnoDB redo log files. Larger files reduce checkpoint frequency and improve write performance. Recommended 25% of buffer pool size.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(6,	'slow_query_log',	'OFF',	'ON',	'Enables logging of slow queries for performance analysis. Essential for identifying optimization opportunities in invoice and product queries.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(7,	'long_query_time',	'10',	'2',	'Log queries taking longer than this many seconds. Set to 2 seconds to catch potentially problematic queries in invoice processing.',	'high',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(8,	'innodb_flush_log_at_trx_commit',	'1',	'2',	'Controls how often InnoDB flushes log to disk. Setting to 2 improves performance with minimal data loss risk (1 second max). Use 1 for maximum durability.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(9,	'table_open_cache',	'4000',	'8000',	'Number of cached table file descriptors. Should be higher than total tables × max_connections. Improves performance when accessing multiple tables.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(10,	'tmp_table_size',	'16M',	'64M',	'Maximum size of internal in-memory temporary tables. Larger size reduces disk-based temporary tables during complex joins and GROUP BY operations.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(11,	'max_heap_table_size',	'16M',	'64M',	'Maximum size for MEMORY (HEAP) tables. Should match tmp_table_size to ensure consistent behavior for temporary tables.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(12,	'key_buffer_size',	'128M',	'256M',	'Cache for MyISAM table indexes. Even with InnoDB, some system tables use MyISAM. 256MB provides good performance for mixed storage engines.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(13,	'sort_buffer_size',	'256K',	'2M',	'Buffer for sorting operations (ORDER BY, GROUP BY). Larger buffer reduces temporary file usage during sorting of invoice lists and reports.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(14,	'read_buffer_size',	'128K',	'256K',	'Buffer for sequential table scans. Improves performance when scanning large tables without indexes. Important for reporting queries.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(15,	'read_rnd_buffer_size',	'256K',	'512K',	'Buffer for reading rows in sorted order after key-based lookups. Improves performance of complex queries with ORDER BY clauses.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(16,	'thread_cache_size',	'8',	'32',	'Number of cached connection threads. Reduces overhead of creating new threads for each connection. Should be set to handle typical concurrent connections.',	'medium',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(17,	'expire_logs_days',	'10',	'7',	'Automatically purge binary logs older than this many days. Saves disk space and reduces maintenance overhead. 7 days provides good balance.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(18,	'max_allowed_packet',	'16M',	'32M',	'Maximum size of packets/strings sent between server and client. Larger size supports bulk operations and large invoice attachments.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(19,	'connect_timeout',	'10',	'20',	'Timeout for initial connection handshake. Increase for slower networks or when clients experience connection timeouts.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(20,	'wait_timeout',	'28800',	'3600',	'Time before closing inactive connections. Reduce to free up resources from abandoned connections. 1 hour (3600s) is good for web applications.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(21,	'interactive_timeout',	'28800',	'3600',	'Similar to wait_timeout but for interactive clients. Should match wait_timeout for consistency.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(22,	'max_connect_errors',	'100',	'1000',	'Maximum failed connection attempts before blocking host. Higher value prevents legitimate users from being blocked due to network issues.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(23,	'innodb_open_files',	'300',	'1000',	'Maximum number of .ibd files InnoDB can keep open. Higher value improves performance with many tables but uses more file descriptors.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(24,	'innodb_io_capacity',	'200',	'1000',	'IO operations per second capability of storage system. Set higher for SSD storage to allow more aggressive flushing and checkpointing.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(25,	'innodb_read_io_threads',	'4',	'8',	'Number of background read IO threads. Increase for better read performance on systems with multiple CPU cores and fast storage.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14'),
(26,	'innodb_write_io_threads',	'4',	'8',	'Number of background write IO threads. Increase for better write performance during heavy insert/update operations.',	'low',	0,	'2025-06-18 09:33:14',	'2025-06-18 09:33:14');
INSERT INTO `pages` (`id`, `parent_id`, `category_id`, `name`, `slug`, `description`, `content`, `meta_title`, `meta_description`, `meta_keywords`, `sort_order`, `main_image`, `images`, `published`, `published_by`, `publishing_start`, `publishing_end`, `created_at`, `updated_at`) VALUES
(1,	NULL,	1,	'{\"cs\":\"Homepage\"}',	'{\"cs\":\"homepage\"}',	'{\"cs\":\"Ahoj\"}',	'{\"cs\":\"<p>toto je obsah<\\/p>\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	1,	'pages/d5a33b609a0bb5df0c00964d1935e143.jpg',	NULL,	1,	NULL,	'2025-06-25 10:21:45',	NULL,	'2025-06-25 04:22:36',	'2025-06-25 04:22:36'),
(2,	NULL,	3,	'{\r\n  \"cs\": \"Vítejte na našich stránkách\",\r\n  \"en\": \"Welcome to our website\",\r\n  \"de\": \"Willkommen auf unserer Webseite\",\r\n  \"sk\": \"Vitajte na našej stránke\"\r\n}',	'{\"cs\":\"domu\", \"en\":\"home\", \"de\":\"home\", \"sk\":\"domov\"}',	'{\r\n  \"cs\": \"Moderní systém pro vytváření faktur s profesionálním vzhledem\",\r\n  \"en\": \"Modern system for creating invoices with a professional appearance\",\r\n  \"de\": \"Modernes System zur Erstellung von Rechnungen mit professionellem Erscheinungsbild\",\r\n  \"sk\": \"Moderný systém na vytváranie faktúr s profesionálnym vzhľadom\"\r\n}',	'{\r\n  \"cs\": \"\\n                <h2>Jednoduché vytváření faktur</h2>\\n                <p>Náš systém vám umožní rychle a jednoduše vytvářet profesionální faktury. Stačí vyplnit základní informace a systém vygeneruje hotovou PDF fakturu.</p>\\n                \\n                <h3>Hlavní funkce:</h3>\\n                <ul>\\n                    <li>Intuitivní uživatelské rozhraní</li>\\n                    <li>Automatické číslování faktur</li>\\n                    <li>Podpora více měn</li>\\n                    <li>Propočet DPH a celkových částek</li>\\n                    <li>Export do PDF formátu</li>\\n                    <li>Správa klientů a dodavatelů</li>\\n                </ul>\\n                \\n                <h3>Pro hosty</h3>\\n                <p>Nepotřebujete registraci! Můžete si vytvořit fakturu jako host a stáhnout ji pomocí bezpečného odkazu.</p>\\n                \\n                <h3>Pro registrované uživatele</h3>\\n                <p>Registrovaní uživatelé mohou využít pokročilé funkce jako ukládání klientů, dodavatelů, produktů a historii faktur.</p>\\n            \",\r\n  \"en\": \"\\n                <h2>Simple Invoice Creation</h2>\\n                <p>Our system allows you to quickly and easily create professional invoices. Just fill in the basic information, and the system will generate a ready-to-use PDF invoice.</p>\\n                \\n                <h3>Main Features:</h3>\\n                <ul>\\n                    <li>Intuitive user interface</li>\\n                    <li>Automatic invoice numbering</li>\\n                    <li>Support for multiple currencies</li>\\n                    <li>VAT and total amount calculation</li>\\n                    <li>Export to PDF format</li>\\n                    <li>Client and supplier management</li>\\n                </ul>\\n                \\n                <h3>For Guests</h3>\\n                <p>No registration required! You can create an invoice as a guest and download it via a secure link.</p>\\n                \\n                <h3>For Registered Users</h3>\\n                <p>Registered users can take advantage of advanced features such as saving clients, suppliers, products, and invoice history.</p>\\n            \",\r\n  \"de\": \"\\n                <h2>Einfache Rechnungserstellung</h2>\\n                <p>Unser System ermöglicht es Ihnen, schnell und einfach professionelle Rechnungen zu erstellen. Füllen Sie einfach die grundlegenden Informationen aus, und das System generiert eine fertige PDF-Rechnung.</p>\\n                \\n                <h3>Hauptfunktionen:</h3>\\n                <ul>\\n                    <li>Intuitive Benutzeroberfläche</li>\\n                    <li>Automatische Rechnungsnummerierung</li>\\n                    <li>Unterstützung für mehrere Währungen</li>\\n                    <li>Berechnung von Mehrwertsteuer und Gesamtbeträgen</li>\\n                    <li>Export in PDF-Format</li>\\n                    <li>Verwaltung von Kunden und Lieferanten</li>\\n                </ul>\\n                \\n                <h3>Für Gäste</h3>\\n                <p>Keine Registrierung erforderlich! Sie können eine Rechnung als Gast erstellen und über einen sicheren Link herunterladen.</p>\\n                \\n                <h3>Für registrierte Benutzer</h3>\\n                <p>Registrierte Benutzer können erweiterte Funktionen wie das Speichern von Kunden, Lieferanten, Produkten und Rechnungsverlauf nutzen.</p>\\n            \",\r\n  \"sk\": \"\\n                <h2>Jednoduché vytváranie faktúr</h2>\\n                <p>Náš systém vám umožní rýchlo a jednoducho vytvárať profesionálne faktúry. Stačí vyplniť základné informácie a systém vygeneruje hotovú PDF faktúru.</p>\\n                \\n                <h3>Hlavné funkcie:</h3>\\n                <ul>\\n                    <li>Intuitívne používateľské rozhranie</li>\\n                    <li>Automatické číslovanie faktúr</li>\\n                    <li>Podpora viacerých mien</li>\\n                    <li>Výpočet DPH a celkových súm</li>\\n                    <li>Export do PDF formátu</li>\\n                    <li>Správa klientov a dodávateľov</li>\\n                </ul>\\n                \\n                <h3>Pre hostí</h3>\\n                <p>Nie je potrebná registrácia! Môžete si vytvoriť faktúru ako hosť a stiahnuť ju pomocou bezpečného odkazu.</p>\\n                \\n                <h3>Pre registrovaných používateľov</h3>\\n                <p>Registrovaní používatelia môžu využívať pokročilé funkcie ako ukladanie klientov, dodávateľov, produktov a históriu faktúr.</p>\\n            \"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	1,	NULL,	NULL,	1,	1,	'2025-06-26 07:14:56',	NULL,	'2025-06-26 03:14:56',	'2025-06-26 03:14:56'),
(3,	NULL,	4,	'{\r\n  \"cs\": \"Fakturace pro firmy\",\r\n  \"en\": \"Invoicing for businesses\",\r\n  \"de\": \"Rechnungsstellung für Unternehmen\",\r\n  \"sk\": \"Fakturácia pre firmy\"\r\n}',	'{\r\n  \"cs\": \"fakturace-pro-firmy\",\r\n  \"en\": \"invoicing-for-businesses\",\r\n  \"de\": \"rechnungsstellung-fur-unternehmen\",\r\n  \"sk\": \"fakturácia-pre-firmy\"\r\n}',	'{\r\n  \"cs\": \"Profesionální fakturace speciálně navržená pro potřeby firem a podnikatelů\",\r\n  \"en\": \"Professional invoicing specially designed for the needs of businesses and entrepreneurs\",\r\n  \"de\": \"Professionelle Rechnungsstellung, speziell für die Bedürfnisse von Unternehmen und Unternehmern entwickelt\",\r\n  \"sk\": \"Profesionálna fakturácia špeciálne navrhnutá pre potreby firiem a podnikateľov\"\r\n}',	'{\r\n  \"cs\": \"\\n                <h2>Fakturace šitá na míru vašemu podnikání</h2>\\n                <p>Naše řešení je ideální pro malé i střední firmy, které potřebují jednoduchou a spolehlivou fakturaci.</p>\\n                \\n                <h3>Výhody pro firmy:</h3>\\n                <ul>\\n                    <li>Automatické ukládání klientů a dodavatelů</li>\\n                    <li>Možnost vytváření šablon produktů</li>\\n                    <li>Pokročilé nástroje pro správu faktur</li>\\n                    <li>Označování faktur jako zaplacené</li>\\n                    <li>Historie všech vystavených faktur</li>\\n                </ul>\\n                \\n                <p>Registrujte se zdarma a vyzkoušejte všechny funkce.</p>\\n            \",\r\n  \"en\": \"\\n                <h2>Invoicing tailored to your business</h2>\\n                <p>Our solution is ideal for small and medium-sized businesses that need simple and reliable invoicing.</p>\\n                \\n                <h3>Benefits for businesses:</h3>\\n                <ul>\\n                    <li>Automatic saving of clients and suppliers</li>\\n                    <li>Ability to create product templates</li>\\n                    <li>Advanced tools for invoice management</li>\\n                    <li>Marking invoices as paid</li>\\n                    <li>History of all issued invoices</li>\\n                </ul>\\n                \\n                <p>Register for free and try all the features.</p>\\n            \",\r\n  \"de\": \"\\n                <h2>Rechnungsstellung, die auf Ihr Unternehmen zugeschnitten ist</h2>\\n                <p>Unsere Lösung ist ideal für kleine und mittelständische Unternehmen, die eine einfache und zuverlässige Rechnungsstellung benötigen.</p>\\n                \\n                <h3>Vorteile für Unternehmen:</h3>\\n                <ul>\\n                    <li>Automatisches Speichern von Kunden und Lieferanten</li>\\n                    <li>Möglichkeit zur Erstellung von Produktvorlagen</li>\\n                    <li>Erweiterte Tools für das Rechnungsmanagement</li>\\n                    <li>Markierung von Rechnungen als bezahlt</li>\\n                    <li>Historie aller ausgestellten Rechnungen</li>\\n                </ul>\\n                \\n                <p>Registrieren Sie sich kostenlos und testen Sie alle Funktionen.</p>\\n            \",\r\n  \"sk\": \"\\n                <h2>Fakturácia prispôsobená vášmu podnikaniu</h2>\\n                <p>Naše riešenie je ideálne pre malé a stredné firmy, ktoré potrebujú jednoduchú a spoľahlivú fakturáciu.</p>\\n                \\n                <h3>Výhody pre firmy:</h3>\\n                <ul>\\n                    <li>Automatické ukladanie klientov a dodávateľov</li>\\n                    <li>Možnosť vytvárania šablón produktov</li>\\n                    <li>Pokročilé nástroje na správu faktúr</li>\\n                    <li>Označovanie faktúr ako zaplatené</li>\\n                    <li>História všetkých vystavených faktúr</li>\\n                </ul>\\n                \\n                <p>Registrujte sa zadarmo a vyskúšajte všetky funkcie.</p>\\n            \"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	1,	NULL,	NULL,	1,	1,	'2025-06-26 07:14:56',	NULL,	'2025-06-26 03:14:56',	'2025-06-26 03:14:56'),
(4,	NULL,	4,	'{\r\n  \"cs\": \"Rychlé faktury pro hosty\",\r\n  \"en\": \"Quick invoices for guests\",\r\n  \"de\": \"Schnelle Rechnungen für Gäste\",\r\n  \"sk\": \"Rýchle faktúry pre hostí\"\r\n}',	'{\r\n  \"cs\": \"rychle-faktury-pro-hosty\",\r\n  \"en\": \"quick-invoices-for-guests\",\r\n  \"de\": \"schnelle-rechnungen-fur-gaste\",\r\n  \"sk\": \"rychle-faktury-pre-hosti\"\r\n}',	'{\r\n  \"cs\": \"Vytvořte si fakturu za pár minut, bez nutnosti registrace\",\r\n  \"en\": \"Create an invoice in a few minutes, no registration required\",\r\n  \"de\": \"Erstellen Sie eine Rechnung in wenigen Minuten, ohne Registrierung\",\r\n  \"sk\": \"Vytvorte si faktúru za pár minút, bez nutnosti registrácie\"\r\n}',	'{\r\n  \"cs\": \"\\n                <h2>Fakturu bez registrace</h2>\\n                <p>Potřebujete rychle vystavit fakturu a nechcete se registrovat? Naše řešení pro hosty je přesně pro vás!</p>\\n                \\n                <h3>Jak to funguje:</h3>\\n                <ol>\\n                    <li>Vyplníte základní údaje o faktuře</li>\\n                    <li>Zadáte položky a ceny</li>\\n                    <li>Systém vygeneruje PDF fakturu</li>\\n                    <li>Dostanete bezpečný odkaz pro stažení</li>\\n                </ol>\\n                \\n                <p><strong>Bezpečnost:</strong> Faktury hostů jsou po 30 dnech automaticky smazány z bezpečnostních důvodů.</p>\\n                \\n                <p>Máte potřebu fakturovat pravidelně? <a href=\\\"/register\\\">Registrujte se zdarma</a> a získejte přístup ke všem funkcím.</p>\\n            \",\r\n  \"en\": \"\\n                <h2>Invoice without registration</h2>\\n                <p>Need to quickly issue an invoice without registering? Our guest solution is perfect for you!</p>\\n                \\n                <h3>How it works:</h3>\\n                <ol>\\n                    <li>Fill in basic invoice details</li>\\n                    <li>Enter items and prices</li>\\n                    <li>The system generates a PDF invoice</li>\\n                    <li>You receive a secure download link</li>\\n                </ol>\\n                \\n                <p><strong>Security:</strong> Guest invoices are automatically deleted after 30 days for security reasons.</p>\\n                \\n                <p>Need to invoice regularly? <a href=\\\"/register\\\">Register for free</a> and gain access to all features.</p>\\n            \",\r\n  \"de\": \"\\n                <h2>Rechnung ohne Registrierung</h2>\\n                <p>Müssen Sie schnell eine Rechnung ausstellen, ohne sich zu registrieren? Unsere Gastlösung ist perfekt für Sie!</p>\\n                \\n                <h3>So funktioniert es:</h3>\\n                <ol>\\n                    <li>Geben Sie die grundlegenden Rechnungsdetails ein</li>\\n                    <li>Fügen Sie Artikel und Preise hinzu</li>\\n                    <li>Das System erstellt eine PDF-Rechnung</li>\\n                    <li>Sie erhalten einen sicheren Download-Link</li>\\n                </ol>\\n                \\n                <p><strong>Sicherheit:</strong> Gastrechnungen werden aus Sicherheitsgründen nach 30 Tagen automatisch gelöscht.</p>\\n                \\n                <p>Müssen Sie regelmäßig Rechnungen ausstellen? <a href=\\\"/register\\\">Registrieren Sie sich kostenlos</a> und erhalten Sie Zugriff auf alle Funktionen.</p>\\n            \",\r\n  \"sk\": \"\\n                <h2>Faktúra bez registrácie</h2>\\n                <p>Potrebujete rýchlo vystaviť faktúru bez registrácie? Naše riešenie pre hostí je presne pre vás!</p>\\n                \\n                <h3>Ako to funguje:</h3>\\n                <ol>\\n                    <li>Vyplníte základné údaje o faktúre</li>\\n                    <li>Zadáte položky a ceny</li>\\n                    <li>Systém vygeneruje PDF faktúru</li>\\n                    <li>Dostanete bezpečný odkaz na stiahnutie</li>\\n                </ol>\\n                \\n                <p><strong>Bezpečnosť:</strong> Faktúry hostí sú po 30 dňoch automaticky vymazané z bezpečnostných dôvodov.</p>\\n                \\n                <p>Potrebujete fakturovať pravidelne? <a href=\\\"/register\\\">Zaregistrujte sa zdarma</a> a získajte prístup ku všetkým funkciám.</p>\\n            \"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	2,	NULL,	NULL,	1,	1,	'2025-06-26 07:14:56',	NULL,	'2025-06-26 03:14:56',	'2025-06-26 03:14:56'),
(5,	NULL,	5,	'{\r\n  \"cs\": \"O aplikaci\",\r\n  \"en\": \"About the application\",\r\n  \"de\": \"Über die Anwendung\",\r\n  \"sk\": \"O aplikácii\"\r\n}',	'{\r\n  \"cs\": \"o-aplikaci\",\r\n  \"en\": \"about-the-application\",\r\n  \"de\": \"uber-die-anwendung\",\r\n  \"sk\": \"o.aplikacii\"\r\n}',	'{\r\n  \"cs\": \"Informace o naší aplikaci pro vytváření faktur\",\r\n  \"en\": \"Information about our invoice creation application\",\r\n  \"de\": \"Informationen über unsere Anwendung zur Rechnungserstellung\",\r\n  \"sk\": \"Informácie o našej aplikácii na vytváranie faktúr\"\r\n}',	'{\r\n  \"cs\": \"\\n                <h2>Jednoduché řešení pro fakturaci</h2>\\n                <p>Naše aplikace vznikla z potřeby mít jednoduché, rychlé a spolehlivé řešení pro vytváření faktur. Ať už jste živnostník, malá firma nebo jen potřebujete občas vystavit fakturu, naše aplikace vám to umožní.</p>\\n                \\n                <h3>Naše hodnoty</h3>\\n                <ul>\\n                    <li><strong>Jednoduchost:</strong> Intuitivní rozhraní, které zvládne každý</li>\\n                    <li><strong>Rychlost:</strong> Fakturu vytvoříte za pár minut</li>\\n                    <li><strong>Spolehlivost:</strong> Vaše data jsou v bezpečí</li>\\n                    <li><strong>Dostupnost:</strong> Základní funkce zdarma, i pro hosty</li>\\n                </ul>\\n                \\n                <h3>Technologie</h3>\\n                <p>Aplikace je postavena na moderních webových technologiích, které zaručují rychlost, bezpečnost a stabilitu.</p>\\n                \\n                <p>Máte dotazy nebo návrhy na vylepšení? Budeme rádi za vaši zpětnou vazbu!</p>\\n            \",\r\n  \"en\": \"\\n                <h2>Simple solution for invoicing</h2>\\n                <p>Our application was created out of the need for a simple, fast, and reliable solution for creating invoices. Whether you are a sole trader, a small business, or just need to occasionally issue an invoice, our application makes it possible.</p>\\n                \\n                <h3>Our values</h3>\\n                <ul>\\n                    <li><strong>Simplicity:</strong> Intuitive interface that anyone can handle</li>\\n                    <li><strong>Speed:</strong> Create an invoice in just a few minutes</li>\\n                    <li><strong>Reliability:</strong> Your data is safe</li>\\n                    <li><strong>Accessibility:</strong> Basic features are free, even for guests</li>\\n                </ul>\\n                \\n                <h3>Technology</h3>\\n                <p>The application is built on modern web technologies that ensure speed, security, and stability.</p>\\n                \\n                <p>Do you have questions or suggestions for improvement? We would love your feedback!</p>\\n            \",\r\n  \"de\": \"\\n                <h2>Einfache Lösung für die Rechnungsstellung</h2>\\n                <p>Unsere Anwendung wurde aus dem Bedürfnis heraus entwickelt, eine einfache, schnelle und zuverlässige Lösung für die Erstellung von Rechnungen zu haben. Egal, ob Sie ein Einzelunternehmer, ein kleines Unternehmen sind oder nur gelegentlich eine Rechnung ausstellen müssen, unsere Anwendung macht es möglich.</p>\\n                \\n                <h3>Unsere Werte</h3>\\n                <ul>\\n                    <li><strong>Einfachheit:</strong> Intuitive Benutzeroberfläche, die jeder bedienen kann</li>\\n                    <li><strong>Schnelligkeit:</strong> Erstellen Sie eine Rechnung in nur wenigen Minuten</li>\\n                    <li><strong>Zuverlässigkeit:</strong> Ihre Daten sind sicher</li>\\n                    <li><strong>Verfügbarkeit:</strong> Grundfunktionen kostenlos, auch für Gäste</li>\\n                </ul>\\n                \\n                <h3>Technologie</h3>\\n                <p>Die Anwendung basiert auf modernen Webtechnologien, die Geschwindigkeit, Sicherheit und Stabilität gewährleisten.</p>\\n                \\n                <p>Haben Sie Fragen oder Verbesserungsvorschläge? Wir freuen uns über Ihr Feedback!</p>\\n            \",\r\n  \"sk\": \"\\n                <h2>Jednoduché riešenie pre fakturáciu</h2>\\n                <p>Naša aplikácia vznikla z potreby mať jednoduché, rýchle a spoľahlivé riešenie pre vytváranie faktúr. Či už ste živnostník, malá firma alebo len potrebujete občas vystaviť faktúru, naša aplikácia vám to umožní.</p>\\n                \\n                <h3>Naše hodnoty</h3>\\n                <ul>\\n                    <li><strong>Jednoduchosť:</strong> Intuitívne rozhranie, ktoré zvládne každý</li>\\n                    <li><strong>Rýchlosť:</strong> Faktúru vytvoríte za pár minút</li>\\n                    <li><strong>Spoľahlivosť:</strong> Vaše dáta sú v bezpečí</li>\\n                    <li><strong>Dostupnosť:</strong> Základné funkcie zdarma, aj pre hostí</li>\\n                </ul>\\n                \\n                <h3>Technológie</h3>\\n                <p>Aplikácia je postavená na moderných webových technológiách, ktoré zaručujú rýchlosť, bezpečnosť a stabilitu.</p>\\n                \\n                <p>Máte otázky alebo návrhy na zlepšenie? Budeme radi za vašu spätnú väzbu!</p>\\n            \"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	1,	NULL,	NULL,	1,	1,	'2025-06-26 07:14:56',	NULL,	'2025-06-26 03:14:56',	'2025-06-26 03:14:56'),
(6,	NULL,	4,	'{\r\n  \"cs\": \"Seznam klientů\",\r\n  \"en\": \"Client list\",\r\n  \"de\": \"Kundenliste\",\r\n  \"sk\": \"Zoznam klientov\"\r\n}',	'{\r\n  \"cs\": \"seznam-klientu\",\r\n  \"en\": \"client.list\",\r\n  \"de\": \"kundenliste\",\r\n  \"sk\": \"zoznam-klientov\"\r\n}',	'{\r\n  \"cs\": \"Funkce pro vytváření a práci s klienty.\",\r\n  \"en\": \"Features for creating and managing clients.\",\r\n  \"de\": \"Funktionen zum Erstellen und Verwalten von Kunden.\",\r\n  \"sk\": \"Funkcie na vytváranie a správu klientov.\"\r\n}',	'{\r\n  \"cs\": \"<p>Systém umožňuje vytvářet osobní seznam klientů, pro jejich snadné načítání do faktur a automatické vytváření dlouhodobých statistik.</p>\",\r\n  \"en\": \"<p>The system allows creating a personal client list for easy loading into invoices and automatic generation of long-term statistics.</p>\",\r\n  \"de\": \"<p>Das System ermöglicht die Erstellung einer persönlichen Kundenliste für das einfache Laden in Rechnungen und die automatische Erstellung langfristiger Statistiken.</p>\",\r\n  \"sk\": \"<p>Systém umožňuje vytvárať osobný zoznam klientov pre jednoduché načítanie do faktúr a automatické vytváranie dlhodobých štatistík.</p>\"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	3,	NULL,	NULL,	1,	1,	'2025-06-27 15:09:14',	NULL,	'2025-06-27 09:28:27',	'2025-06-27 10:07:22'),
(7,	NULL,	4,	'{\r\n  \"cs\": \"Seznam dodavatelů\",\r\n  \"en\": \"Supplier list\",\r\n  \"de\": \"Lieferantenliste\",\r\n  \"sk\": \"Zoznam dodávateľov\"\r\n}',	'{\r\n  \"cs\": \"seznam-dodavatelu\",\r\n  \"en\": \"supplier-list\",\r\n  \"de\": \"lieferantenliste\",\r\n  \"sk\": \"zoznam-dodavatelov\"\r\n}',	'{\r\n  \"cs\": \"Funkce pro vytváření dodavatelů.\",\r\n  \"en\": \"Features for creating suppliers.\",\r\n  \"de\": \"Funktionen zum Erstellen von Lieferanten.\",\r\n  \"sk\": \"Funkcie na vytváranie dodávateľov.\"\r\n}',	'{\r\n  \"cs\": \"<p>Systém umožňuje vytvářet osobní seznam dodavatelů, pro jejich snadné načítání do faktur a automatické vytváření dlouhodobých statistik. Dodavatelům je také možné přidávat jednoduché produkty, aby to pro Vás bylo opravdu co nejrychlejší.</p>\\r\\n\\r\\n<p>&nbsp;</p>\",\r\n  \"en\": \"<p>The system allows creating a personal supplier list for easy loading into invoices and automatic generation of long-term statistics. Suppliers can also be assigned simple products to make it as quick as possible for you.</p>\\r\\n\\r\\n<p>&nbsp;</p>\",\r\n  \"de\": \"<p>Das System ermöglicht die Erstellung einer persönlichen Lieferantenliste für das einfache Laden in Rechnungen und die automatische Erstellung langfristiger Statistiken. Lieferanten können auch einfache Produkte zugewiesen werden, um es für Sie so schnell wie möglich zu machen.</p>\\r\\n\\r\\n<p>&nbsp;</p>\",\r\n  \"sk\": \"<p>Systém umožňuje vytvárať osobný zoznam dodávateľov pre jednoduché načítanie do faktúr a automatické vytváranie dlhodobých štatistík. Dodávateľom je tiež možné pridať jednoduché produkty, aby to pre vás bolo naozaj čo najrýchlejšie.</p>\\r\\n\\r\\n<p>&nbsp;</p>\"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	4,	NULL,	NULL,	1,	1,	'2025-06-27 16:05:07',	NULL,	'2025-06-27 10:05:43',	'2025-06-27 10:09:15'),
(8,	NULL,	4,	'{\r\n  \"cs\": \"Soukromé statistiky\",\r\n  \"en\": \"Private statistics\",\r\n  \"de\": \"Private Statistiken\",\r\n  \"sk\": \"Súkromné štatistiky\"\r\n}',	'{\r\n  \"cs\": \"soukrome-statistiky\",\r\n  \"en\": \"private-statistics\",\r\n  \"de\": \"private-statistiken\",\r\n  \"sk\": \"sukromne-statistiky\"\r\n}',	'{\r\n  \"cs\": \"Automatické vytváření statistik na Vašem dashboardu.\",\r\n  \"en\": \"Automatic generation of statistics on your dashboard.\",\r\n  \"de\": \"Automatische Erstellung von Statistiken auf Ihrem Dashboard.\",\r\n  \"sk\": \"Automatické vytváranie štatistík na vašom dashboarde.\"\r\n}',	'{\r\n  \"cs\": \"<p>Každý přihlášený uživatel má svůj osobní Dashboard (nástěnku) s rychlým přehledem a podrobnými statistikami.</p>\",\r\n  \"en\": \"<p>Each logged-in user has their personal Dashboard with a quick overview and detailed statistics.</p>\",\r\n  \"de\": \"<p>Jeder angemeldete Benutzer hat sein persönliches Dashboard mit einer schnellen Übersicht und detaillierten Statistiken.</p>\",\r\n  \"sk\": \"<p>Každý prihlásený používateľ má svoj osobný Dashboard s rýchlym prehľadom a podrobnými štatistikami.</p>\"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	5,	NULL,	NULL,	1,	1,	'2025-06-27 16:12:23',	NULL,	'2025-06-27 10:12:26',	'2025-06-27 10:12:26'),
(9,	NULL,	4,	'{\r\n  \"cs\": \"Soukromé produkty\",\r\n  \"en\": \"Private products\",\r\n  \"de\": \"Private Produkte\",\r\n  \"sk\": \"Súkromné produkty\"\r\n}',	'{\r\n  \"cs\": \"soukrome-produkty\",\r\n  \"en\": \"private-products\",\r\n  \"de\": \"private-produkte\",\r\n  \"sk\": \"sukromne-produkty\"\r\n}',	'{\r\n  \"cs\": \"Každý uživatel má možnost si vytvářet své produkty.\",\r\n  \"en\": \"Each user has the ability to create their own products.\",\r\n  \"de\": \"Jeder Benutzer hat die Möglichkeit, seine eigenen Produkte zu erstellen.\",\r\n  \"sk\": \"Každý používateľ má možnosť vytvárať svoje vlastné produkty.\"\r\n}',	'{\r\n  \"cs\": \"<p>Můžete si vytvářet své produkty na základě Vašich nejčastějších položek na faktuře. Následně si je můžete do faktury pouze přidat v podobě položky faktury. Vše se pak na faktuře automaticky přepočítá, tak aby s tím nebyla žádná starost.</p>\",\r\n  \"en\": \"<p>You can create your products based on your most frequent invoice items. Subsequently, you can simply add them to the invoice as an invoice item. Everything will then be automatically recalculated on the invoice, so there is no hassle.</p>\",\r\n  \"de\": \"<p>Sie können Ihre Produkte basierend auf Ihren häufigsten Rechnungspositionen erstellen. Anschließend können Sie diese einfach als Rechnungsposition zur Rechnung hinzufügen. Alles wird dann automatisch auf der Rechnung neu berechnet, sodass es keine Mühe bereitet.</p>\",\r\n  \"sk\": \"<p>Môžete si vytvárať svoje produkty na základe vašich najčastejších položiek na faktúre. Následne si ich môžete do faktúry jednoducho pridať ako položku faktúry. Všetko sa potom na faktúre automaticky prepočíta, aby ste s tým nemali žiadne starosti.</p>\"\r\n}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	'{\"cs\":\"\"}',	6,	NULL,	NULL,	1,	1,	'2025-06-26 16:37:00',	NULL,	'2025-06-27 10:17:14',	'2025-06-27 10:38:21'),
(55,	NULL,	6,	'{\"cs\":\"Funkce\",\"en\":\"Features\",\"de\":\"Funktionen\",\"sk\":\"Funkcie\"}',	'{\"cs\":\"funkce\",\"en\":\"features\",\"de\":\"funktionen\",\"sk\":\"funkcie\"}',	'{\"cs\":\"V\\u0161echny funkce na\\u0161eho faktura\\u010dn\\u00edho syst\\u00e9mu na jednom m\\u00edst\\u011b\",\"en\":\"All features of our invoicing system in one place\",\"de\":\"Alle Funktionen unseres Rechnungssystems an einem Ort\",\"sk\":\"V\\u0161etky funkcie n\\u00e1\\u0161ho faktura\\u010dn\\u00e9ho syst\\u00e9mu na jednom mieste\"}',	'{\"cs\":\"\\n            <div class=\\\"bg-white dark:bg-gray-800 py-24 sm:py-5\\\">\\n                <div class=\\\"mx-auto max-w-7xl px-6 lg:px-8\\\">\\n                    <div class=\\\"mx-auto max-w-2xl lg:text-center\\\">\\n                        <h2 class=\\\"text-base font-semibold leading-7 text-indigo-600\\\">Fakturace snadno<\\/h2>\\n                        <p class=\\\"mt-2 text-3xl font-bold tracking-tight text-gray-900 dark:text-gray-400 sm:text-4xl\\\">\\n                            V\\u0161e, co pot\\u0159ebujete pro profesion\\u00e1ln\\u00ed fakturaci\\n                        <\\/p>\\n                        <p class=\\\"mt-6 text-lg leading-8 text-gray-600 dark:text-gray-400\\\">\\n                            N\\u00e1\\u0161 faktura\\u010dn\\u00ed syst\\u00e9m obsahuje v\\u0161echny n\\u00e1stroje pot\\u0159ebn\\u00e9 pro efektivn\\u00ed spr\\u00e1vu faktur, klient\\u016f a plateb.\\n                        <\\/p>\\n                    <\\/div>\\n                    \\n                    <div class=\\\"mx-auto mt-16 max-w-2xl sm:mt-20 lg:mt-24 lg:max-w-4xl\\\">\\n                        <dl class=\\\"grid max-w-xl grid-cols-1 gap-x-8 gap-y-10 lg:max-w-none lg:grid-cols-2 lg:gap-y-16\\\">\\n                            <div class=\\\"relative pl-16\\\">\\n                                <dt class=\\\"text-base font-semibold leading-7 text-gray-900 dark:text-gray-400\\\">\\n                                    <div class=\\\"a